//! `levels/ffa_defrag.lvl` (generated by `scripts/gen_defrag_level.py`): THE DE-FRAG ASSEMBLY. Pinned: a bottomless
//! map with three central layers, four velocity tubes whose doors line up with the bridges / ledges on every layer,
//! four mid-layer conveyors that reach the door ledges, a data-purge sweeper that kills in the open and spares the
//! sheltered, supported spawns and cubes, and 30 s of live play that stays finite and honest.

use std::f32::consts::{PI, TAU};
use std::time::Duration;

use shinobi_proto::intent::{ClientPacket, PlayerIntent, ViewState, PITCH_LEVEL};
use shinobi_proto::quant::{dq_yaw, q_yaw};
use shinobi_sim::character::{sync_body_colliders, Cfg};
use shinobi_sim::level::{parse_level_file, LevelFile, ShapeKind};
use shinobi_sim::power::PowerKind;
use shinobi_sim::pvp::KILL_PLANE_Y;
use shinobi_sim::rapier3d::prelude::*;
use shinobi_sim::tick::Server;

const LAYERS: [f32; 3] = [5.0, 25.0, 50.0];

fn load() -> LevelFile {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../levels/ffa_defrag.lvl");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    parse_level_file(&text).unwrap_or_else(|e| panic!("ffa_defrag.lvl: {e}"))
}

fn server(l: &LevelFile) -> Server {
    let mut s = Server::new(Cfg::default());
    l.level.apply_to_server(&mut s);
    s.set_level_features(l.features.clone());
    s.set_spawns(l.level.spawns.clone());
    s
}

/// Highest box top under (x, z) at or below `y` + 0.1.
fn support_under(l: &LevelFile, x: f32, y: f32, z: f32) -> Option<f32> {
    l.level
        .boxes
        .iter()
        .filter(|b| (x - b.center[0]).abs() <= b.half[0] && (z - b.center[2]).abs() <= b.half[2])
        .map(|b| b.center[1] + b.half[1])
        .filter(|top| *top <= y + 0.1)
        .fold(None, |m: Option<f32>, t| Some(m.map_or(t, |m| m.max(t))))
}

fn angle_diff(to: f32, from: f32) -> f32 {
    (to - from + PI).rem_euclid(TAU) - PI
}

#[test]
fn bottomless_three_layers_four_tubes_four_conveyors_one_purge_and_the_counts() {
    let l = load();
    assert!(l.level.boxes.len() <= 1800);
    assert!(l.level.boxes.iter().all(|b| b.half[0] <= 20.0 || b.half[2] <= 20.0), "no ground plane");
    assert!(l.level.boxes.iter().all(|b| b.center[1] - b.half[1] > KILL_PLANE_Y + 10.0), "the kill plane is well below everything");
    assert_eq!(l.level.spawns.len(), 10);
    for top in [LAYERS[1], LAYERS[2]] {
        assert_eq!(l.level.spawns.iter().filter(|s| (s[1] - 0.81 - top).abs() < 1e-3).count(), 5, "5 spawns on y={top}");
    }
    assert_eq!(l.pickups.iter().filter(|p| p.kind == PowerKind::None).count(), 4);
    assert!(l.pickups.iter().all(|p| p.kind == PowerKind::None), "no weapon pedestals: everyone owns everything");
    let f = &l.features;
    assert_eq!(f.shapes.iter().filter(|s| s.kind == ShapeKind::Tube).count(), 20, "4 tubes x 5 sections");
    assert_eq!(f.movers.iter().filter(|m| m.tag == "conveyor" && m.solid).count(), 4);
    assert_eq!(f.hazards.len(), 1);
    assert_eq!(f.hazards[0].tag, "data_purge");
    assert_eq!(f.zones.iter().filter(|z| z.tag == "overload_pillar").count(), 6);
}

#[test]
fn spawns_and_cubes_stand_on_permanent_platforms() {
    let l = load();
    for s in &l.level.spawns {
        let top = support_under(&l, s[0], s[1] - 0.81, s[2]).unwrap_or_else(|| panic!("spawn {s:?} floats"));
        assert!((s[1] - 0.81 - top).abs() < 0.05, "spawn {s:?} stands on y={top}");
    }
    for p in &l.pickups {
        let top = support_under(&l, p.pos[0], p.pos[1] - 1.0, p.pos[2]).unwrap_or_else(|| panic!("cube {:?} floats", p.pos));
        assert!((p.pos[1] - 1.0 - top).abs() < 0.05);
    }
    assert!(l.level.boxes.iter().all(|b| b.hp == 0.0), "spawn platforms and routes are permanent");
}

#[test]
fn every_tube_door_lines_up_with_a_bridge_or_ledge_and_no_wall_segment_blocks_it() {
    let l = load();
    let doors: Vec<_> = l.features.shapes.iter().filter(|s| s.tuning.contains_key("door_count")).collect();
    assert_eq!(doors.len(), 12, "4 tubes x 3 layers");
    for t in &doors {
        let layer = LAYERS.iter().copied().find(|y| (t.center[1] - t.extent / 2.0..t.center[1] + t.extent / 2.0).contains(y)).expect("a layer in each door band");
        // the route runs from the tube centre toward the origin
        let (dx, dz) = (-t.center[0], -t.center[2]);
        let len = (dx * dx + dz * dz).sqrt();
        let (ux, uz) = (dx / len, dz / len);
        let door_point = [t.center[0] + ux * t.radius, t.center[2] + uz * t.radius];
        // a walkable surface spans the doorway at the layer height
        let top = support_under(&l, door_point[0], layer, door_point[1]);
        assert_eq!(top, Some(layer), "tube at {:?}: nothing to walk on through the door", t.center);
        // no remaining wall segment sits within 3 m of the doorway
        for seg in t.segments() {
            let d = ((seg.center[0] - door_point[0]).powi(2) + (seg.center[2] - door_point[1]).powi(2)).sqrt();
            assert!(d > 3.0, "tube at {:?}: a wall segment {d} m from the doorway", t.center);
        }
    }
}

#[test]
fn the_conveyors_run_from_the_mid_platform_edge_to_the_door_ledges() {
    let l = load();
    for m in l.features.movers.iter().filter(|m| m.tag == "conveyor") {
        let a = m.axis.index();
        let (p0, p1) = (m.pos_at(0), m.pos_at(m.period_ticks));
        let (near, far) = if p0[a].abs() < p1[a].abs() { (p0, p1) } else { (p1, p0) };
        assert!((near[a].abs() - m.half[a] - 10.0).abs() < 0.01, "touches the platform edge: {near:?}");
        let tip = far[a].signum() * (far[a].abs() + m.half[a] - 0.25);
        let mut probe = [far[0], far[2]];
        probe[if a == 0 { 0 } else { 1 }] = tip;
        assert_eq!(support_under(&l, probe[0], 25.0, probe[1]), Some(25.0), "reaches a door ledge at {probe:?}");
        assert!((m.center[1] + m.half[1] - 25.0).abs() < 1e-4, "flush with the mid layer");
    }
}

#[test]
fn the_purge_descends_on_time_and_kills_in_the_open_but_not_under_cover() {
    let l = load();
    let h = &l.features.hazards[0];
    let movers = &l.features.movers;
    let period = h.period_ticks;
    let first = (0..period).find(|t| h.is_active(*t)).expect("an active window");
    assert!(first >= 30 * 60, "nobody spawns into the first purge (first at tick {first})");
    assert!(!h.is_active(0) && !h.is_telegraph(0));
    assert!(h.is_telegraph(first - 1), "telegraphed right before the descent");
    assert!((h.center_at(first, movers)[1] - 55.0).abs() < 1e-4);
    assert!((h.center_at(first + 240, movers)[1] - 30.0).abs() < 0.2, "half way down after 4 s");
    assert!(h.center_at(first + 479, movers)[1] < 5.5);
    assert!((h.center_at(first + 480, movers)[1] - 55.0).abs() < 1e-4, "reset after 8 s");

    let mut s = server(&l);
    let spots = [
        (1u16, [0.0, 50.81, 0.0]),  // top platform, open sky
        (2u16, [3.0, 5.81, 3.0]),   // low platform, under the mid platform
        (3u16, [0.0, 21.81, 8.0]),  // mid-layer drop ledge, under the mid platform's edge
    ];
    for (id, pos) in spots {
        s.add_player(id, pos);
        let body = s.players.iter().find(|p| p.id == id).unwrap().ch.body;
        s.world.bodies[body].set_position(Isometry::translation(pos[0], pos[1], pos[2]), true);
        sync_body_colliders(&mut s.world, body);
    }
    s.world.queries.update(&s.world.colliders);
    let cfg = *s.cfg();
    let mut hit = [false; 4];
    for tick in first..first + 480 {
        s.level_features.end_tick(&s.world, &mut s.players, tick, &cfg, true);
        for c in s.level_features.hazard_contacts() {
            hit[s.players[c.victim].id as usize] = true;
            assert!(c.amount >= 1000.0, "lethal");
        }
    }
    assert!(hit[1], "the player in the open is purged");
    assert!(!hit[2], "the low platform is sheltered by the mid platform");
    assert!(!hit[3], "the drop ledge is a safe pocket");
}

#[test]
fn thirty_seconds_with_live_features_is_clean() {
    const TICKS: u32 = 30 * 60;
    let l = load();
    let mut s = server(&l);
    for i in 0..3u16 {
        s.add_player(i + 1, l.level.spawns[i as usize * 3]);
    }
    for t in 0..TICKS {
        let tick = s.tick;
        assert_eq!(tick, t);
        for id in 1..=3u16 {
            let p = s.players.iter().find(|p| p.id == id).unwrap();
            let pos = p.pos(&s.world);
            let want = (-pos[0]).atan2(-pos[2]);
            let step = angle_diff(want, dq_yaw(p.yaw)).clamp(-0.21, 0.21);
            let pkt = ClientPacket {
                ack_snapshot_tick: tick.saturating_sub(6).max(1),
                view: ViewState { from_tick: tick.saturating_sub(6).max(1), alpha: 0 },
                intents: vec![PlayerIntent { tick, move_z: 127, aim_yaw: q_yaw(dq_yaw(p.yaw) + step), aim_pitch: PITCH_LEVEL, ..Default::default() }],
                ..Default::default()
            };
            s.ingest(id, &pkt.encode().unwrap());
        }
        s.frame(Duration::from_nanos(16_666_667));
        for p in &s.players {
            let pos = p.pos(&s.world);
            assert!(pos.iter().all(|c| c.is_finite()) && pos[0].abs() < 65.0 && pos[2].abs() < 65.0, "tick {t}: player {} at {pos:?}", p.id);
            assert_eq!(p.guard.strikes, 0, "tick {t}: player {} collected a strike", p.id);
        }
    }
}
